DROP TABLE IF EXISTS `encuestas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `encuestas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ticket_id` int NOT NULL,
  `resolucion` int DEFAULT NULL,
  `asertividad` int DEFAULT NULL,
  `rapidez` int DEFAULT NULL,
  `calidad` int DEFAULT NULL,
  `promedio` float DEFAULT NULL,
  `comentarios` longtext,
  `creado` datetime NOT NULL,
  `vencimiento` datetime DEFAULT NULL,
  `estado` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_encuestas_tickets_idx` (`ticket_id`),
  CONSTRAINT `fk_encuestas_tickets` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=847 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

