INSERT INTO `entradas` VALUES (28,'2024-07-22 10:30:23','Nueva Página de Tickets','Hemos rediseñado completamente la página de tickets para que sea más fácil de manejar y entender. Ahora, encontrar y gestionar tus tickets es más intuitivo que nunca','ecbf7b5b8d0a7af7a10e981205ebde5a','novedad','si','JEAN PAUL RODRIGUEZ'),(29,'2024-07-19 17:06:22','Evita los accidentes antes de que sucedan','Mantén la laptop alejada de alimentos y bebidas.','9422fbe3bcb8854df8e0bec59be81648','recomendacion','si','ALEXANDER PEÑA'),(32,'2024-07-22 16:15:46','Interfaz Amigable','La nueva interfaz es más limpia y organizada, permitiéndote navegar y resolver tus tickets con mayor rapidez y eficiencia.','','novedad','si','JEAN PAUL RODRIGUEZ'),(34,'2024-07-23 16:01:10','Uso de Contraseñas Seguras','Utiliza contraseñas fuertes y únicas para cada cuenta y dispositivo. Considera el uso de un gestor de contraseñas para mantenerlas organizadas.','','recomendacion','si','JEAN PAUL RODRIGUEZ'),(35,'2024-07-24 10:41:29','Encuesta de Satisfacción','Queremos saber tu opinión. Completa nuestra encuesta de satisfacción y participa en el sorteo de una cuenta de Spotify Premium por un mes.','','novedad','si','JEAN PAUL RODRIGUEZ'),(36,'2024-07-29 15:31:04','Actualizaciones Regulares','Continuaremos realizando actualizaciones periódicas para mejorar aún más tu experiencia.','','novedad','si','Jean Paul Rodriguez');
